record.field:
params = env['ir.config_parameter'].sudo() # Older versions kept one plaintext key here and handed it to every user. params.set_param('yengec_connector.api_key', False)
# Odoo only stores key hashes, so mint a fresh key for the current user. # Earlier keys are kept: Yengeç may still be using one of them. # Non-admins may only mint expiring keys (1 day by default) and Odoo has no refresh, # so mint a persistent one in sudo. sudo keeps the uid: the key still belongs to the user. api_key = env['res.users.apikeys'].sudo()._generate('rpc', 'Yengeç Connector', None)
integration = env.context.get('yengec_integration') or '' query = [ ('base_url', params.get_param('web.base.url', '')), ('database', env.cr.dbname), ('username', env.user.login), ('integration', integration), ('utm_source', 'odoo'), ('utm_medium', 'odoo-app'), ('utm_campaign', 'yengec_' + (integration or 'connector')), ] # urllib is not available to server actions, so escape what would break the query string. encoded = '&'.join( '%s=%s' % (name, value.replace('%', '%25').replace('&', '%26').replace('#', '%23').replace('+', '%2B').replace(' ', '%20')) for name, value in query ) action = { 'type': 'ir.actions.act_url', 'target': 'new', # The fragment is never sent to a server, so the key stays out of access logs. 'url': 'https://app.yengec.co/auth/odoo?%s#api_key=%s' % (encoded, api_key), }
